style.css:
/* =========================================================
   REDDIT → GENERIC "NEWS" SITE
   ========================================================= */


/* ---------------------------------------------------------
   1. HIDE REDDIT LOGOS / BRANDING
   --------------------------------------------------------- */

/* Reddit logo SVG / icon */
a[href="/"] svg,
a[href="https://www.reddit.com/"] svg,
header [aria-label*="Reddit"] svg,
header [aria-label*="reddit"] svg {
    display: none !important;
}


/* Hide common Reddit wordmark elements */
reddit-logo,
reddit-logo-large,
[class*="reddit-logo"],
[class*="redditLogo"],
[class*="wordmark"],
[class*="Wordmark"] {
    display: none !important;
}


/* ---------------------------------------------------------
   2. REPLACE TOP LOGO WITH "news"
   --------------------------------------------------------- */

/* Homepage/logo link */
header a[href="/"],
header a[href="https://www.reddit.com/"] {
    font-size: 0 !important;
    text-decoration: none !important;
}


/* Our replacement title */
header a[href="/"]::after,
header a[href="https://www.reddit.com/"]::after {
    content: "news";
    font-size: 22px !important;
    font-weight: 700 !important;
    letter-spacing: -0.5px;
    color: inherit;
}


/* ---------------------------------------------------------
   3. REMOVE REDDIT BRAND NAME WHERE POSSIBLE
   --------------------------------------------------------- */

[class*="reddit-brand"],
[class*="redditBrand"],
[class*="RedditBrand"] {
    display: none !important;
}


/* ---------------------------------------------------------
   4. OPTIONAL: REMOVE "Reddit" FOOTER LINKS / TEXT AREAS
   --------------------------------------------------------- */

footer a[href*="redditinc.com"],
footer a[href*="/about"],
footer a[href*="/press"],
footer a[href*="/advertising"] {
    display: none !important;
}


/* ---------------------------------------------------------
   5. REMOVE COMMUNITY ICONS
   Gives subreddit links a cleaner news-site appearance
   --------------------------------------------------------- */

a[href^="/r/"] img,
a[href*="reddit.com/r/"] img {
    display: none !important;
}


/* ---------------------------------------------------------
   6. CLEAN UP SUBREDDIT LINKS
   --------------------------------------------------------- */

a[href^="/r/"],
a[href*="reddit.com/r/"] {
    text-decoration: none !important;
}
